MergeSort(A, indiceInicio, indiceFin):
    // Si solo hay un elemento en el arreglo, regresar
    if indiceInicio == indiceFin:
        return

    indiceMedio = (indiceInicio + indiceFin) / 2

    // Ordenar la mitad izquierda del arreglo
    MergeSort(A, indiceInicio, indiceMedio)

    // Ordenar la mitad derecha del arreglo
    MergeSort(A, indiceMedio + 1, indiceFin)

    // Combinar los dos arreglos ordenados
    Merge(A, indiceInicio, indiceFin)

Merge(A, indiceInicio, indiceFin):
    indiceMedio = (indiceInicio + indiceFin) / 2
    indiceIzquierda = indiceInicio
    indiceDerecha = indiceMedio + 1

    // Arreglo temporal para guardar el resultado ordenado
    arregloTemporal[]

    // Recorrer ambas mitades del arreglo
    for i in range(indiceInicio, indiceFin+1):
        // Si la mitad izquierda ya terminó, agregar desde la mitad derecha
        if indiceIzquierda > indiceMedio:
            arregloTemporal[i] = A[indiceDerecha]
            indiceDerecha++

        // Si la mitad derecha ya terminó, agregar desde la mitad izquierda
        else if indiceDerecha > indiceFin:
            arregloTemporal[i] = A[indiceIzquierda]
            indiceIzquierda++

        // Comparar los elementos actuales y agregar el menor
        else if A[indiceIzquierda] < A[indiceDerecha]:
            arregloTemporal[i] = A[indiceIzquierda]
            indiceIzquierda++
        else:
            arregloTemporal[i] = A[indiceDerecha]
            indiceDerecha++

    // Copiar arregloTemporal de vuelta a A
    for i in range(indiceInicio, indiceFin+1):
        A[i] = arregloTemporal[i]

def suma_arreglo(arr):
  suma = 0
  for n in arr:
    suma += n
  return suma

